<section class="problem sec dark gridlines" id="problem" aria-labelledby="problem-h"><div class="wrap"><div class="sec-head"><div><span class="label"><b>003</b> / The problem</span><h2 id="problem-h">The leads arrive <span class="mark">after</span> the desk goes quiet.</h2></div></div><div class="stats"><div class="stat b"><span class="label">Unanswered calls</span><div class="n" data-cnt="62" data-sfx="%">62%</div><p>of calls to small businesses go <b>unanswered</b>.</p></div><div class="stat o"><span class="label">Time to cold</span><div class="n" data-cnt="5" data-sfx=" min">5 min</div><p>is how fast a lead goes cold. After that, <b>most book with someone else</b>.</p></div><div class="stat g"><span class="label">After hours</span><div class="n" data-cnt="4" data-pfx="1 in ">1 in 4</div><p>bookings come in after hours, <b>when nobody is at the desk</b>.</p></div></div><p class="after">Ondesk answers all of them, in seconds, at 2 AM or 2 PM.</p></div></section>
<script>
(function(){
  var fired = false;
  function run(el){
    var target = +el.dataset.cnt;
    var sfx = el.dataset.sfx || '';
    var pfx = el.dataset.pfx || '';
    var t0 = Date.now(), dur = 1200;
    (function tick(){
      var p = Math.min(1,(Date.now()-t0)/dur);
      var ease = 1 - Math.pow(1-p,3);
      el.textContent = pfx + Math.round(ease*target) + sfx;
      if(p < 1) requestAnimationFrame(tick);
    })();
  }
  var wrap = document.querySelector('.problem .stats');
  if(!wrap) return;
  new IntersectionObserver(function(e,obs){
    if(fired||!e[0].isIntersecting) return;
    fired = true; obs.disconnect();
    wrap.querySelectorAll('[data-cnt]').forEach(run);
  },{threshold:0.3}).observe(wrap);
})();
</script>
HTML;

