    /* ── build Elementor elements array ─────────────────────────── */

    function ondesk_container(string $id, string $html, array $extra_settings = []): array {
        $settings = array_merge([
            'flex_direction'  => 'column',
            'content_width'   => 'full',
            'padding'         => ['unit' => 'px', 'top' => '0', 'right' => '0', 'bottom' => '0', 'left' => '0', 'isLinked' => false],
        ], $extra_settings);

        return [
            'id'       => $id,
            'elType'   => 'container',
            'isInner'  => false,
            'settings' => $settings,
            'elements' => [
                [
                    'id'         => $id . 'w',
                    'elType'     => 'widget',
                    'widgetType' => 'html',
                    'settings'   => ['html' => $html],
                    'elements'   => [],
                ],
            ],
        ];
    }

    $elements = [
        ondesk_container('a0ann00', $sec_announce),
        ondesk_container('a0nav00', $sec_nav),
        ondesk_container('a0her00', $sec_hero),
        ondesk_container('a0tru00', $sec_trust),
        ondesk_container('a0prb00', $sec_problem),
        ondesk_container('a0how00', $sec_how),
        ondesk_container('a0cnv00', $sec_conn_v),
        ondesk_container('a0btw00', $sec_between),
        ondesk_container('a0ftr00', $sec_features),
        ondesk_container('a0inb00', $sec_inbox),
        ondesk_container('a0uca00', $sec_usecases),
        ondesk_container('a0cnd00', $sec_conn_dark),
        ondesk_container('a0tes00', $sec_testimonials),
        ondesk_container('a0int00', $sec_integrations),
        ondesk_container('a0pri00', $sec_pricing),
        ondesk_container('a0faq00', $sec_faq),
        ondesk_container('a0dem00', $sec_demo),
        ondesk_container('a0foo00', $sec_footer),
    ];

    $elementor_data = wp_json_encode($elements, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);

    /* ── create (or find) the page ─────────────────────────────── */
    $existing = get_page_by_path('ondesk-landing');
    if ($existing) {
        $page_id = $existing->ID;
    } else {
        $page_id = wp_insert_post([
            'post_title'   => 'Ondesk — AI Front Desk for Local Businesses',
            'post_name'    => 'ondesk-landing',
            'post_status'  => 'publish',
            'post_type'    => 'page',
            'post_content' => '',
        ]);
    }

    if (is_wp_error($page_id) || ! $page_id) return;

    // Elementor meta
    update_post_meta($page_id, '_elementor_edit_mode', 'builder');
    update_post_meta($page_id, '_elementor_template_type', 'wp-page');
    // wp_slash() counteracts wp_unslash() inside update_metadata(), preserving JSON escape sequences
    update_post_meta($page_id, '_elementor_data', wp_slash($elementor_data));
    update_post_meta($page_id, '_elementor_page_settings', [
        'hide_title'  => 'yes',
        'page_layout' => 'full_width',
    ]);
    // Elementor Canvas template (no theme header/footer)
    update_post_meta($page_id, '_wp_page_template', 'elementor_canvas');

    // Set as WordPress front page
    update_option('show_on_front', 'page');
    update_option('page_on_front', $page_id);

    // SEO meta via Rank Math
    update_post_meta($page_id, 'rank_math_title', 'Ondesk — AI Front Desk for Local Businesses');
    update_post_meta($page_id, 'rank_math_description', 'Ondesk answers every chat, WhatsApp and DM in seconds, books straight into your calendar and follows up while you work.');
    update_post_meta($page_id, 'rank_math_og_title', 'Ondesk — Never miss another booking.');
    update_post_meta($page_id, 'rank_math_og_description', 'AI front desk for clinics, gyms, salons and real estate agents. 14 days free, no credit card.');

    // Mark done
    update_option('ondesk_setup_done_v4', true);
}, 1);
